const $=id=>document.getElementById(id),cats={course:['课程','#738d64','#edf2e6'],exam:['考试','#bc8552','#faf0e2'],report:['汇报','#8d80aa','#f0ecf5'],life:['生活','#648e9a','#eaf1f2']};const key='daynest-events-v1';let events=[];try{events=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(events))events=[]}catch{}const now=new Date(),fmt=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,today=fmt(now);let selected=today,month=new Date(now.getFullYear(),now.getMonth(),1),view='calendar',editing=null,active=new Set(Object.keys(cats));const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const style=t=>`--color:${cats[t][1]};--bg:${cats[t][2]}`;function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),6500)}function save(){try{localStorage.setItem(key,JSON.stringify(events));return true}catch{toast('保存失败：浏览器存储不可用，请检查存储权限。');return false}}function sorted(es){return es.sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))}function filtered(){return events.filter(e=>active.has(e.type))}
$('filters').innerHTML=Object.entries(cats).map(([k,c])=>`<label class="filter"><i class="dot" style="background:${c[1]}"></i>${c[0]}<input type="checkbox" value="${k}" checked aria-label="显示${c[0]}"></label>`).join('');$('legend').innerHTML=Object.values(cats).map(c=>`<span><i class="dot" style="background:${c[1]}"></i>${c[0]}</span>`).join('');$('type').innerHTML=Object.entries(cats).map(([k,c])=>`<option value="${k}">${c[0]}</option>`).join('');$('greeting').textContent=`${now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})} · 给重要的事，留一个位置。`;
function render(){const ym=fmt(month).slice(0,7),me=events.filter(e=>e.date.startsWith(ym));$('statToday').textContent=events.filter(e=>e.date===today).length;$('statMonth').textContent=me.length;$('statDone').textContent=me.filter(e=>e.done).length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('calendarBody').classList.toggle('hidden',view!=='calendar');$('listBody').classList.toggle('hidden',view==='calendar');$('monthControls').classList.toggle('hidden',view!=='calendar');$('search').classList.toggle('hidden',view==='calendar');$('monthTitle').innerHTML=view==='calendar'?`${month.getFullYear()}年 ${month.getMonth()+1}月 <span>${month.toLocaleDateString('en',{month:'long'}).toUpperCase()}</span>`:view==='today'?'今日安排':'全部日程';let start=new Date(month);start.setDate(1-((start.getDay()+6)%7));let count=Math.ceil((((month.getDay()+6)%7)+new Date(month.getFullYear(),month.getMonth()+1,0).getDate())/7)*7;let html='';for(let i=0;i<count;i++){let d=new Date(start);d.setDate(start.getDate()+i);let date=fmt(d),es=sorted(filtered().filter(e=>e.date===date));html+=`<div class="cell ${d.getMonth()!==month.getMonth()?'out':''} ${date===today?'today':''} ${date===selected?'selected':''}" data-date="${date}" role="button" tabindex="0" aria-label="${date}，${es.length}项日程"><span class="num">${d.getDate()}</span>${es.slice(0,2).map(e=>`<div class="event ${e.done?'done':''}" style="${style(e.type)}">${e.start} ${esc(e.title)}</div>`).join('')}${es.length>2?`<small style="font-size:9px;color:#8b9783">＋${es.length-2} 项日程</small>`:''}</div>`}$('grid').innerHTML=html;const query=$('search').value.toLowerCase();const list=sorted(filtered().filter(e=>(view!=='today'||e.date===today)&&[e.title,e.location,e.notes].join(' ').toLowerCase().includes(query)));$('listBody').innerHTML=list.length?list.map(e=>`<div class="listrow" data-edit="${e.id}" role="button" tabindex="0"><i class="dot" style="background:${cats[e.type][1]}"></i><small>${e.date}<br>${e.start}–${e.end}</small><div class="${e.done?'done':''}">${esc(e.title)}<br><small>${cats[e.type][0]} · ${esc(e.location)||'未设置地点'}</small></div></div>`).join(''):'<div class="empty">暂时没有日程<br>点击「新建日程」，安排下一件重要的事。</div>';renderDay()}
function renderDay(){let d=new Date(selected+'T00:00:00'),es=sorted(filtered().filter(e=>e.date===selected));$('dayTitle').textContent=`${d.getMonth()+1}月${d.getDate()}日${selected===today?' · 今天':''}`;$('dayMeta').textContent=`${d.toLocaleDateString('zh-CN',{weekday:'long'})} / ${es.length} 项日程`;$('schedule').innerHTML=es.length?es.map(e=>`<article class="item" style="${style(e.type)}"><div class="itemtime">${e.start} — ${e.end}</div><div class="itemcard"><span class="badge">● ${cats[e.type][0]}</span><h3 class="${e.done?'done':''}">${esc(e.title)}</h3><div class="details">⌖ ${esc(e.location)||'未设置地点'}${e.notes?'<br>'+esc(e.notes):''}<br>♧ ${+e.reminder<0?'不提醒':+e.reminder===0?'准时提醒':'提前 '+e.reminder+' 分钟'}</div><div class="itembuttons"><button data-done="${e.id}">${e.done?'↶ 设为未完成':'✓ 标记完成'}</button><button data-edit="${e.id}">编辑 ↗</button></div></div></article>`).join(''):'<div class="empty">一段留白，也很好。<br>这一天还没有安排</div>'}
function openForm(id){editing=id||null;let e=events.find(e=>e.id===id);$('form').reset();$('modalTitle').textContent=e?'编辑日程':'新建日程';$('delete').classList.toggle('hidden',!e);for(let f of ['title','date','type','start','end','location','reminder','notes'])if(e)$(f).value=e[f]||'';if(!e)$('date').value=selected;$('modal').showModal();$('title').focus()}
$('new').onclick=() =>openForm();$('addDay').onclick=()=>openForm();$('cancel').onclick=()=>$('modal').close();$('form').onsubmit=e=>{e.preventDefault();if($('end').value<=$('start').value){toast('结束时间需要晚于开始时间，请将跨天日程分开记录。');return}if(!$('title').value.trim()){toast('请填写日程名称');return}let old=events.find(x=>x.id===editing),item={id:editing||crypto.randomUUID(),done:old?.done||false};for(let f of ['title','date','type','start','end','location','reminder','notes'])item[f]=$(f).value.trim();if(old&&['date','start','reminder'].every(k=>old[k]===item[k]))item.fired=old.fired;const previous=events;events=events.filter(x=>x.id!==item.id).concat(item);if(!save()){events=previous;return}selected=item.date;month=new Date(selected+'T00:00:00');month.setDate(1);$('modal').close();render();toast('日程已保存')};$('delete').onclick=()=>{if(!confirm('确定删除这个日程吗？'))return;const previous=events;events=events.filter(e=>e.id!==editing);if(!save()){events=previous;return}$('modal').close();render();toast('日程已删除')};document.addEventListener('click',e=>{let edit=e.target.closest('[data-edit]'),done=e.target.closest('[data-done]'),cell=e.target.closest('[data-date]'),nav=e.target.closest('[data-view]');if(edit)openForm(edit.dataset.edit);if(done){let item=events.find(x=>x.id===done.dataset.done);item.done=!item.done;if(!save())item.done=!item.done;render()}if(cell){selected=cell.dataset.date;render()}if(nav){view=nav.dataset.view;if(view==='today')selected=today;render()}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-date],[data-edit]')){e.preventDefault();e.target.click()}});$('filters').onchange=()=>{active=new Set([...document.querySelectorAll('.filter input:checked')].map(x=>x.value));render()};$('search').oninput=render;$('prev').onclick=()=>{month.setMonth(month.getMonth()-1);render()};$('next').onclick=()=>{month.setMonth(month.getMonth()+1);render()};$('today').onclick=()=>{selected=today;month=new Date(now.getFullYear(),now.getMonth(),1);render()};function notifyLabel(){$('notify').textContent=('Notification'in window&&Notification.permission==='granted')?'♧ 提醒已开启':'♧ 开启提醒'}$('notify').onclick=async()=>{if(!('Notification'in window)){toast('当前浏览器不支持系统通知，网页内仍会显示提醒。');return}try{let p=await Notification.requestPermission();toast(p==='granted'?'提醒已开启，请保持网页打开。':'未获得通知权限；网页打开时仍会显示提醒。');notifyLabel()}catch{toast('无法启用系统通知；网页内提醒仍然可用。')}};function checkReminders(){let dirty=false,t=Date.now();events.forEach(e=>{if(e.done||e.fired||+e.reminder<0)return;let due=new Date(e.date+'T'+e.start).getTime()-Number(e.reminder)*60000;if(t>=due&&t<=new Date(e.date+'T'+e.end).getTime()){e.fired=true;dirty=true;toast(`日程提醒：${e.title} · ${e.start}${e.location?' · '+e.location:''}`);if('Notification'in window&&Notification.permission==='granted')try{new Notification('日序 · 日程提醒',{body:`${e.title}\n${e.date} ${e.start} ${e.location||''}`,tag:e.id})}catch{}}});if(dirty)save()}window.addEventListener('focus',checkReminders);window.addEventListener('storage',e=>{if(e.key===key){try{const v=JSON.parse(e.newValue||'[]');if(Array.isArray(v)){events=v;render()}}catch{}}});render();notifyLabel();checkReminders();setInterval(checkReminders,5000);
